package com.ktd.analyzer.view;

import android.content.Context;import android.graphics.*;import android.view.*;import com.ktd.analyzer.data.ScanData;import java.util.ArrayList;import java.util.Comparator;

public final class IsoSurfaceView extends View{
    private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private ScanData data;private int palette=0;private float yaw=-25,pitch=58,zoom=1;private float lx,ly;private final ScaleGestureDetector scaler;
    public IsoSurfaceView(Context c){super(c);setBackgroundColor(Color.rgb(6,12,18));scaler=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(.55f,Math.min(3f,zoom*d.getScaleFactor()));invalidate();return true;}});}
    public void setData(ScanData d){data=d;invalidate();}public void setPalette(int v){palette=v;invalidate();}
    private float[] proj(float x,float y,float z){double yr=Math.toRadians(yaw),pr=Math.toRadians(pitch);float x1=(float)(x*Math.cos(yr)-y*Math.sin(yr));float y1=(float)(x*Math.sin(yr)+y*Math.cos(yr));float y2=(float)(y1*Math.cos(pr)-z*Math.sin(pr));float s=Math.min(getWidth(),getHeight())*.35f*zoom;return new float[]{getWidth()/2f+x1*s,getHeight()*.54f+y2*s};}
    protected void onDraw(Canvas c){super.onDraw(c);drawBox(c);if(data==null)return;float max=data.maxAbs();ArrayList<Blob> blobs=new ArrayList<>();for(int r=0;r<data.rows;r++)for(int co=0;co<data.cols;co++)if(data.filled[r][co]){float v=data.delta[r][co];if(Math.abs(v)<=10)continue;float x=-1+2f*co/Math.max(1,data.cols-1f),y=-1+2f*r/Math.max(1,data.rows-1f);float strength=Math.min(1f,(Math.abs(v)-10f)/Math.max(10f,max-10f));int layers=3+(int)(strength*5);for(int k=0;k<layers;k++){float z=-.65f+k*(1.25f/Math.max(1,layers-1));blobs.add(new Blob(x,y,z,v,strength));}}blobs.sort(Comparator.comparingDouble(b->b.z));for(Blob b:blobs){float[] q=proj(b.x,b.y,b.z);float rad=(10+36*b.s)*zoom;p.setStyle(Paint.Style.FILL);int col=ColorMaps.color(palette,b.v,max);p.setColor(col);p.setAlpha((int)(55+105*b.s));c.drawOval(q[0]-rad*1.5f,q[1]-rad*.65f,q[0]+rad*1.5f,q[1]+rad*.65f,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.2f);p.setColor(ColorMaps.color(palette,b.v,max));p.setAlpha(150);c.drawOval(q[0]-rad*1.5f,q[1]-rad*.65f,q[0]+rad*1.5f,q[1]+rad*.65f,p);}p.setAlpha(255);}
    private void drawBox(Canvas c){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.argb(190,230,240,248));float[][] a=new float[8][];int i=0;for(int z=-1;z<=1;z+=2)for(int y=-1;y<=1;y+=2)for(int x=-1;x<=1;x+=2)a[i++]=proj(x,y,z*.7f);int[][] e={{0,1},{0,2},{0,4},{1,3},{1,5},{2,3},{2,6},{3,7},{4,5},{4,6},{5,7},{6,7}};for(int[] v:e)c.drawLine(a[v[0]][0],a[v[0]][1],a[v[1]][0],a[v[1]][1],p);}
    public boolean onTouchEvent(MotionEvent e){scaler.onTouchEvent(e);if(e.getPointerCount()>1)return true;if(e.getAction()==MotionEvent.ACTION_DOWN){lx=e.getX();ly=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){yaw+=(e.getX()-lx)*.35f;pitch=Math.max(15,Math.min(82,pitch+(e.getY()-ly)*.25f));lx=e.getX();ly=e.getY();invalidate();return true;}return true;}
    private static class Blob{float x,y,z,v,s;Blob(float x,float y,float z,float v,float s){this.x=x;this.y=y;this.z=z;this.v=v;this.s=s;}}
}
